'use client';
import React, { useEffect, useRef } from 'react';
import Image from 'next/image';
import { motion } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/dist/ScrollTrigger';

const content = {
  EN: {
    title: "About Me",
    subtitle: "Building digital experiences from Jeddah to the world",
    bio: "As a Computer Science graduate from King Abdulaziz University, I blend Saudi innovation with global tech trends. My journey in tech started with curiosity and evolved into a passion for creating impactful digital solutions.",
    education: {
      degree: "Bachelor in Computer Science",
      university: "King Abdulaziz University (KAU)",
      year: "2020-2024"
    }
  },
  AR: {
    title: "نبذة عني",
    subtitle: "أبني تجارب رقمية من جدة إلى العالم",
    bio: "كخريج علوم الحاسب من جامعة الملك عبدالعزيز، أمزج بين الابتكار السعودي واتجاهات التقنية العالمية. بدأت رحلتي في التقنية بالفضول وتطورت إلى شغف بإنشاء حلول رقمية مؤثرة.",
    education: {
      degree: "بكالوريوس علوم الحاسب",
      university: "جامعة الملك عبدالعزيز",
      year: "٢٠٢٠-٢٠٢٤"
    }
  }
};

const ShapeDivider = ({ theme, position }) => (
  <div className={`absolute ${position === 'top' ? 'top-0' : 'bottom-0'} left-0 w-full overflow-hidden ${position === 'top' ? '' : 'rotate-180'}`}>
    <svg data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 120" preserveAspectRatio="none" className="relative block w-full h-[60px]">
      <path d="M321.39,56.44c58-10.79,114.16-30.13,172-41.86,82.39-16.72,168.19-17.73,250.45-.39C823.78,31,906.67,72,985.66,92.83c70.05,18.48,146.53,26.09,214.34,3V0H0V27.35A600.21,600.21,0,0,0,321.39,56.44Z" 
            style={{ fill: theme.surface }}></path>
    </svg>
  </div>
);

const AnimatedBackground = ({ theme }) => {
  const backgroundRef = useRef(null);

  useEffect(() => {
    const particles = gsap.utils.toArray('.particle');
    gsap.to(particles, {
      x: "random(-100, 100, 5)",
      y: "random(-100, 100, 5)",
      scale: "random(0.5, 1.5)",
      duration: "random(2, 6)",
      opacity: "random(0.3, 0.7)",
      repeat: -1,
      yoyo: true,
      ease: "power1.inOut",
      stagger: {
        each: 0.1,
        from: "random"
      }
    });
  }, []);

  return (
    <div ref={backgroundRef} className="absolute inset-0 overflow-hidden pointer-events-none">
      {[...Array(50)].map((_, i) => (
        <div
          key={i}
          className="particle absolute w-2 h-2 rounded-full"
          style={{
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            background: theme.primary,
            opacity: Math.random() * 0.5 + 0.3,
          }}
        />
      ))}
    </div>
  );
};

export default function About() {
  const { theme, language, isDark } = useTheme();
  const currentContent = content[language];
  const isRTL = language === 'AR';
  
  const sectionRef = useRef(null);
  const textRef = useRef(null);
  const imageRef = useRef(null);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);
    
    const ctx = gsap.context(() => {
      // Text content animation
      gsap.from(textRef.current, {
        y: 50,
        opacity: 0,
        duration: 1.2,
        scrollTrigger: {
          trigger: textRef.current,
          start: "top 80%",
          end: "top 20%",
          toggleActions: "play none none reverse"
        }
      });

      // Image animation
      gsap.from(imageRef.current, {
        scale: 0.8,
        opacity: 0,
        duration: 1.2,
        scrollTrigger: {
          trigger: imageRef.current,
          start: "top 80%",
          end: "top 20%",
          toggleActions: "play none none reverse"
        }
      });

      // Particle animation
      gsap.to('.particle', {
        y: 'random(-100, 100)',
        x: 'random(-100, 100)',
        opacity: 'random(0.3, 0.7)',
        duration: 'random(3, 5)',
        repeat: -1,
        yoyo: true,
        ease: 'power1.inOut',
        stagger: {
          amount: 4,
          from: 'random'
        }
      });
    }, sectionRef);

    return () => ctx.revert();
  }, []);

  return (
    <section 
      id="about" 
      ref={sectionRef}
      className="min-h-screen py-20 relative overflow-hidden"
      dir={isRTL ? 'rtl' : 'ltr'}
    >
      <motion.div
        className={`absolute inset-0 bg-gradient-to-br ${theme.bg}`}
        initial={false}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5 }}
      />

      <AnimatedBackground theme={theme} />

      <ShapeDivider theme={theme} position="top" />

      <div className="max-w-6xl mx-auto px-6 relative z-10">
        <div className="relative grid md:grid-cols-12 gap-12 items-center">
          <div ref={textRef} className="md:col-span-7 space-y-8">
            <div className="text-center md:text-left">
              <motion.h2 
                className="text-4xl md:text-5xl font-bold mb-4"
                style={{ color: theme.text }}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6 }}
              >
                {currentContent.title}
              </motion.h2>
              <motion.p 
                className="text-lg md:text-xl italic"
                style={{ color: theme.primary }}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: 0.2 }}
              >
                {currentContent.subtitle}
              </motion.p>
            </div>

            <motion.div 
              className="p-8 rounded-2xl backdrop-blur-lg"
              style={{ 
                backgroundColor: `${theme.cardBg}`,
                border: `1px solid ${theme.border}`,
                boxShadow: `0 8px 32px ${theme.primary}10`
              }}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.3 }}
            >
              <p 
                className="text-lg leading-relaxed"
                style={{ color: theme.textSecondary }}
              >
                {currentContent.bio}
              </p>
            </motion.div>

            <motion.div
              className="p-6 rounded-xl backdrop-blur-md transform hover:scale-105 transition-all duration-300"
              style={{ 
                backgroundColor: theme.cardBg,
                border: `1px solid ${theme.border}`,
                boxShadow: `0 4px 20px ${theme.primary}15`
              }}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.4 }}
              whileHover={{
                boxShadow: `0 8px 32px ${theme.primary}25`,
                y: -5
              }}
            >
              <div className="space-y-2">
                <h3 
                  className="text-xl font-semibold"
                  style={{ color: theme.primary }}
                >
                  {currentContent.education.university}
                </h3>
                <p style={{ color: theme.textSecondary }}>
                  {currentContent.education.degree}
                </p>
                <p 
                  className="font-medium"
                  style={{ color: theme.primary }}
                >
                  {currentContent.education.year}
                </p>
              </div>
            </motion.div>
          </div>

          <div ref={imageRef} className="md:col-span-5 relative">
            <motion.div
              className="relative aspect-square rounded-full overflow-hidden shadow-2xl"
              whileHover={{ 
                scale: 1.05,
                boxShadow: `0 25px 50px -12px ${theme.primary}30`
              }}
              transition={{ duration: 0.3 }}
              style={{
                border: `4px solid ${theme.primary}30`,
              }}
            >
              <Image
                src="/images/undraw_dev-focus_dd7i.png"
                alt="Developer Profile"
                fill
                className="object-cover transform transition-transform duration-700 hover:scale-110"
                priority
              />
              <div 
                className="absolute inset-0 opacity-60 transition-opacity duration-300 hover:opacity-40"
                style={{ 
                  background: `radial-gradient(circle at 30% 30%, transparent 0%, ${theme.primary}30 100%)`
                }}
              />
            </motion.div>
            
            <div 
              className="absolute -z-10 w-full h-full rounded-full blur-3xl opacity-20"
              style={{ 
                background: `radial-gradient(circle at 50% 50%, ${theme.primary}, transparent 70%)`,
                transform: 'translate(-50%, -50%)',
                left: '50%',
                top: '50%'
              }}
            />
          </div>
        </div>
      </div>

      <ShapeDivider theme={theme} position="bottom" />
    </section>
  );
}

