const NavItem = ({ title, active, onClick, theme }) => (
  <motion.button
    onClick={onClick}
    className="relative px-4 py-2 group"
    whileHover={{ scale: 1.05 }}
    whileTap={{ scale: 0.95 }}
  >
    <motion.span
      className="relative z-10 text-lg transition-colors duration-200"
      style={{ color: active ? theme.primary : theme.textSecondary }}
    >
      {title}
    </motion.span>
    {active && (
      <motion.div
        layoutId="navIndicator"
        className="absolute inset-0 rounded-md"
        style={{ backgroundColor: `${theme.primary}15` }}
        transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
      />
    )}
  </motion.button>
);

const ShapeDivider = ({ theme }) => (
  <div className="absolute bottom-0 left-0 w-full overflow-hidden rotate-180">
    <svg data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 120" preserveAspectRatio="none" className="relative block w-full h-[60px]">
      <path d="M321.39,56.44c58-10.79,114.16-30.13,172-41.86,82.39-16.72,168.19-17.73,250.45-.39C823.78,31,906.67,72,985.66,92.83c70.05,18.48,146.53,26.09,214.34,3V0H0V27.35A600.21,600.21,0,0,0,321.39,56.44Z" 
            style={{ fill: theme.surface }}></path>
    </svg>
  </div>
);

const AnimatedBackground = ({ theme }) => {
  const backgroundRef = useRef(null);

  useEffect(() => {
    const particles = gsap.utils.toArray('.particle');
    gsap.to(particles, {
      x: "random(-100, 100, 5)",
      y: "random(-100, 100, 5)",
      scale: "random(0.5, 1.5)",
      duration: "random(2, 6)",
      opacity: "random(0.3, 0.7)",
      repeat: -1,
      yoyo: true,
      ease: "power1.inOut",
      stagger: {
        each: 0.1,
        from: "random"
      }
    });
  }, []);

  return (
    <div ref={backgroundRef} className="absolute inset-0 overflow-hidden pointer-events-none">
      {[...Array(50)].map((_, i) => (
        <div
          key={i}
          className="particle absolute w-2 h-2 rounded-full"
          style={{
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            background: theme.primary,
            opacity: Math.random() * 0.5 + 0.3,
          }}
        />
      ))}
    </div>
  );
};

export default function Hero() {
  const { isDark, toggleTheme, theme, language, toggleLanguage } = useTheme();
  const [activeSection, setActiveSection] = useState('home');
  const currentContent = content[language];
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const heroRef = useRef(null);

  const navItems = [
    { title: currentContent.nav.home, id: 'home' },
    { title: currentContent.nav.about, id: 'about' },
    { title: currentContent.nav.skills, id: 'skills' },
    { title: currentContent.nav.projects, id: 'projects' },
    { title: currentContent.nav.contact, id: 'contact' },
  ];

  useEffect(() => {
    const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });

    tl.from(heroRef.current, { opacity: 0, duration: 1 })
      .from('.hero-content > *', { 
        y: 30, 
        opacity: 0, 
        stagger: 0.2,
        duration: 0.8
      }, '-=0.5')
      .from('.nav-item', { 
        y: -20, 
        opacity: 0, 
        stagger: 0.1, 
        duration: 0.5 
      }, '-=0.5');

    const handleScroll = () => {
      const sections = ['home', 'about', 'skills', 'projects', 'contact'];
      const currentPos = window.scrollY + 100;

      for (const section of sections) {
        const element = document.getElementById(section);
        if (element) {
          const { offsetTop, offsetHeight } = element;
          if (currentPos >= offsetTop && currentPos < offsetTop + offsetHeight) {
            setActiveSection(section);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollTo = (id) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
    setActiveSection(id);
    setIsMenuOpen(false);
  };

  return (
    <div id="home" ref={heroRef} className="relative min-h-screen overflow-hidden">
      {/* New Tech Vibe Background */}
      <motion.div
        className={`absolute inset-0 bg-gradient-to-br from-blue-500 via-indigo-500 to-purple-600 opacity-90`}
        initial={false}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5 }}
      />
      
      <AnimatedBackground theme={theme} />

      <nav className={`fixed top-0 left-0 right-0 z-50 transition-colors duration-300 ${theme.navBg}`}>
        <div className="max-w-6xl mx-auto px-6">
          <div className="flex items-center justify-between h-16">
            <div className="hidden md:flex space-x-1">
              {navItems.map((item) => (
                <NavItem
                  key={item.id}
                  title={item.title}
                  active={activeSection === item.id}
                  onClick={() => scrollTo(item.id)}
                  theme={theme}
                />
              ))}
            </div>

            <div className="md:hidden">
              <motion.button
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="p-2 rounded-lg"
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
              >
                <div className="w-6 h-0.5 mb-1.5" style={{ backgroundColor: theme.primary }} />
                <div className="w-6 h-0.5 mb-1.5" style={{ backgroundColor: theme.primary }} />
                <div className="w-6 h-0.5" style={{ backgroundColor: theme.primary }} />
              </motion.button>
            </div>

            <div className="flex items-center gap-4">
              <motion.a
                href="https://github.com/Seba-00"
                target="_blank"
                rel="noopener noreferrer"
                whileHover={{ scale: 1.1, y: -2 }}
                whileTap={{ scale: 0.95 }}
                className="p-2 rounded-lg hover:bg-opacity-10 transition-colors duration-200"
                style={{ color: theme.primary }}
              >
                <FaGithub className="w-5 h-5" />
              </motion.a>
              <motion.a
                href="https://www.linkedin.com/in/seba-00/"
                target="_blank"
                rel="noopener noreferrer"
                whileHover={{ scale: 1.1, y: -2 }}
                whileTap={{ scale: 0.95 }}
                className="p-2 rounded-lg hover:bg-opacity-10 transition-colors duration-200"
                style={{ color: theme.primary }}
              >
                <FaLinkedin className="w-5 h-5" />
              </motion.a>
              <motion.button
                onClick={toggleTheme}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                className="p-2 rounded-lg"
              >
                {isDark ? <FiSun className="w-5 h-5" /> : <FiMoon className="w-5 h-5" />}
              </motion.button>
              <motion.button
                onClick={toggleLanguage}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                className="p-2 rounded-lg"
              >
                <IoLanguage className="w-5 h-5" />
              </motion.button>
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Content */}
      <div className="relative z-10 hero-content text-center pt-32 md:pt-40 pb-16">
        <h2 className="text-4xl font-extrabold text-white">{currentContent.greeting}</h2>
        <h1 className="text-5xl md:text-6xl text-white mt-2">{currentContent.name}</h1>
        <h3 className="text-2xl text-white mt-6">{currentContent.subtitle}</h3>

        <div className="mt-8">
          <TypeAnimation
            sequence={currentContent.typewriter}
            speed={50}
            wrapper="h3"
            className="text-lg md:text-2xl text-white font-semibold"
            repeat={Infinity}
          />
        </div>

        <motion.button
          onClick={() => scrollTo('projects')}
          className="mt-10 px-6 py-3 text-lg text-white font-semibold rounded-md bg-gradient-to-r from-indigo-500 to-blue-500 hover:from-blue-500 hover:to-indigo-500"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {currentContent.projectButton}
        </motion.button>
      </div>

      <ShapeDivider theme={theme} />
    </div>
  );
}
