'use client';
import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/dist/ScrollTrigger';
import { FaReact, FaNodeJs, FaPython, FaDatabase, FaDocker, FaAws } from 'react-icons/fa';
import { SiTypescript, SiGraphql } from 'react-icons/si';

const content = {
  EN: {
    title: "Technical Skills",
    skills: [
      { name: "React", icon: FaReact, level: 90 },
      { name: "Node.js", icon: FaNodeJs, level: 85 },
      { name: "TypeScript", icon: SiTypescript, level: 88 },
      { name: "Python", icon: FaPython, level: 80 },
      { name: "SQL", icon: FaDatabase, level: 75 },
      { name: "GraphQL", icon: SiGraphql, level: 70 },
      { name: "Docker", icon: FaDocker, level: 65 },
      { name: "AWS", icon: FaAws, level: 60 },
    ]
  },
  AR: {
    title: "المهارات التقنية",
    skills: [
      { name: "React", icon: FaReact, level: 90 },
      { name: "Node.js", icon: FaNodeJs, level: 85 },
      { name: "TypeScript", icon: SiTypescript, level: 88 },
      { name: "Python", icon: FaPython, level: 80 },
      { name: "SQL", icon: FaDatabase, level: 75 },
      { name: "GraphQL", icon: SiGraphql, level: 70 },
      { name: "Docker", icon: FaDocker, level: 65 },
      { name: "AWS", icon: FaAws, level: 60 },
    ]
  }
};

const ShapeDivider = ({ theme, position }) => (
  <div className={`absolute ${position === 'top' ? 'top-0' : 'bottom-0'} left-0 w-full overflow-hidden ${position === 'top' ? '' : 'rotate-180'}`}>
    <svg data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 120" preserveAspectRatio="none" className="relative block w-full h-[100px]">
      <path d="M985.66,92.83C906.67,72,823.78,31,743.84,14.19c-82.26-17.34-168.06-16.33-250.45.39-57.84,11.73-114,31.07-172,41.86A600.21,600.21,0,0,1,0,27.35V120H1200V95.8C1132.19,118.92,1055.71,111.31,985.66,92.83Z" 
            style={{ fill: theme.surface }}></path>
    </svg>
  </div>
);

const AnimatedBackground = ({ theme }) => {
  const backgroundRef = useRef(null);

  useEffect(() => {
    const particles = gsap.utils.toArray('.particle');
    gsap.to(particles, {
      x: "random(-100, 100, 5)",
      y: "random(-100, 100, 5)",
      scale: "random(0.5, 1.5)",
      duration: "random(2, 6)",
      opacity: "random(0.3, 0.7)",
      repeat: -1,
      yoyo: true,
      ease: "power1.inOut",
      stagger: {
        each: 0.1,
        from: "random"
      }
    });
  }, []);

  return (
    <div ref={backgroundRef} className="absolute inset-0 overflow-hidden pointer-events-none">
      {[...Array(50)].map((_, i) => (
        <div
          key={i}
          className="particle absolute w-2 h-2 rounded-full"
          style={{
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            background: theme.primary,
            opacity: Math.random() * 0.5 + 0.3,
          }}
        />
      ))}
    </div>
  );
};

const SkillCard = ({ skill, theme, index }) => {
  const cardRef = useRef(null);

  useEffect(() => {
    gsap.to(cardRef.current, {
      y: "random(-20, 20)",
      duration: 2,
      repeat: -1,
      yoyo: true,
      ease: "power1.inOut",
      delay: index * 0.2
    });
  }, [index]);

  return (
    <motion.div
      ref={cardRef}
      className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 flex flex-col items-center justify-center"
      style={{ 
        backgroundColor: theme.cardBg,
        border: `2px solid ${theme.primary}`,
      }}
      whileHover={{ scale: 1.05, rotate: 5 }}
      whileTap={{ scale: 0.95 }}
    >
      <skill.icon size={48} style={{ color: theme.primary }} className="mb-4" />
      <h3 className="text-xl font-semibold mb-2" style={{ color: theme.primary }}>{skill.name}</h3>
      <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700 mt-2">
        <div 
          className="h-2.5 rounded-full" 
          style={{ width: `${skill.level}%`, backgroundColor: theme.primary }}
        ></div>
      </div>
    </motion.div>
  );
};

export default function Skills() {
  const { theme, language } = useTheme();
  const currentContent = content[language];
  const isRTL = language === 'AR';
  
  const sectionRef = useRef(null);
  const skillsRef = useRef(null);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);
    
    const ctx = gsap.context(() => {
      gsap.from(skillsRef.current.children, {
        y: 50,
        opacity: 0,
        duration: 0.8,
        stagger: 0.2,
        scrollTrigger: {
          trigger: skillsRef.current,
          start: "top 80%",
          end: "bottom 20%",
          toggleActions: "play none none reverse"
        }
      });
    }, sectionRef);

    return () => ctx.revert();
  }, []);

  return (
    <section 
      id="skills" 
      ref={sectionRef}
      className="min-h-screen py-20 relative overflow-hidden"
      dir={isRTL ? 'rtl' : 'ltr'}
    >
      <motion.div
        className={`absolute inset-0 bg-gradient-to-br ${theme.bg}`}
        initial={false}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5 }}
      />

      <AnimatedBackground theme={theme} />

      <ShapeDivider theme={theme} position="top" />

      <div className="max-w-6xl mx-auto px-6 relative z-10">
        <motion.h2 
          className="text-4xl md:text-5xl font-bold mb-12 text-center"
          style={{ color: theme.text }}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
        >
          {currentContent.title}
        </motion.h2>

        <div ref={skillsRef} className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-8">
          {currentContent.skills.map((skill, index) => (
            <SkillCard key={index} skill={skill} theme={theme} index={index} />
          ))}
        </div>
      </div>

      <ShapeDivider theme={theme} position="bottom" />
    </section>
  );
}

